(function(){const viewport=document.getElementById("propertyCarouselViewport"),list=document.getElementById("propertyCarouselList");if(!viewport||!list)return;const slides=Array.from(list.children),prevBtn=document.getElementById("propertyPrevBtn"),nextBtn=document.getElementById("propertyNextBtn"),dotsContainer=document.getElementById("propertyDots");function perView(){const w=window.innerWidth;return w>=950?3:w>=650?2:1}function renderDots(){const maxIndex=Math.max(0,slides.length-perView());dotsContainer.innerHTML=Array.from({length:maxIndex+1},(_,i)=>`<div class="dot${i===0?" active":""}" data-index="${i}"></div>`).join(""),dotsContainer.querySelectorAll(".dot").forEach((dot)=>{dot.addEventListener("click",()=>{const i=parseInt(dot.dataset.index,10);slides[i]&&viewport.scrollTo({left:slides[i].offsetLeft,behavior:"smooth"})})})}function updateActiveState(){let closest=0,closestDist=1/0;slides.forEach((slide,i)=>{const dist=Math.abs(slide.offsetLeft-viewport.scrollLeft);dist<closestDist&&(closestDist=dist,closest=i)}),dotsContainer.querySelectorAll(".dot").forEach((dot,i)=>{dot.classList.toggle("active",i===closest)}),prevBtn.disabled=viewport.scrollLeft<=1,nextBtn.disabled=viewport.scrollLeft>=viewport.scrollWidth-viewport.clientWidth-1}function stepWidth(){return slides.length>1?slides[1].offsetLeft-slides[0].offsetLeft:slides[0]?slides[0].getBoundingClientRect().width:0}function scrollByCards(direction){viewport.scrollBy({left:direction*stepWidth(),behavior:"smooth"})}prevBtn.addEventListener("click",()=>scrollByCards(-1)),nextBtn.addEventListener("click",()=>scrollByCards(1));let scrollTimer;viewport.addEventListener("scroll",()=>{clearTimeout(scrollTimer),scrollTimer=setTimeout(updateActiveState,100)},{passive:true});let resizeTimer;window.addEventListener("resize",()=>{clearTimeout(resizeTimer),resizeTimer=setTimeout(()=>{renderDots(),updateActiveState()},150)}),renderDots(),updateActiveState(),typeof ResizeObserver!=="undefined"&&(()=>{const resizeObserver=new ResizeObserver(()=>updateActiveState());resizeObserver.observe(list),resizeObserver.observe(viewport)})(),window.addEventListener("load",updateActiveState)})();
